def add_task(self, expire_ms: int, task_id: str) -> None:
        with self._lock:
            delay = expire_ms - self.current_ms
            if delay < self.tick_ms:
                self.buckets[0].append((expire_ms, task_id))
            elif delay < self.interval_ms:
                idx = (expire_ms // self.tick_ms) % self.wheel_size
                self.buckets[idx].append((expire_ms, task_id))
            else:
                if self.overflow is None:
                    self.overflow = TimeWheel(self.interval_ms, self.wheel_size, self.current_ms)
                self.overflow.add_task(expire_ms, task_id)
